using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A 0/1 knapsack in each language whose test of whether an item fits - weight &lt; j - leaves out the item that fits exactly,
/// with the change that lets it in; the same knapsacks letting it in, and programs near the mistake but not it, which are
/// left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class ExactFitLeftOutTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes, one a line.</summary>
    public static TheoryData<string, string, string, int, int, int, string> Mistakes => new()
    {
        { "best.py", "def knapsack(capacity, items):\n    best = [0] * (capacity + 1)\n    for weight, value in items:\n        for j in range(capacity, 0, -1):\n            if weight < j:\n                best[j] = max(best[j], value + best[j - weight])\n    return best[capacity]\n\n\nprint(knapsack(7, [(5, 10), (4, 40), (6, 30), (3, 50)]))\n", "logic-python-exact-fit-left-out", 5, 5, 1, "            if weight <= j:" },
        { "knapsack.c", "#include <stdio.h>\n\n#define MAX(a, b) ((a) > (b) ? (a) : (b))\n\nint main(void) {\n    int weights[4] = {5, 4, 6, 3}, values[4] = {10, 40, 30, 50};\n    static int table[5][8];\n    for (int i = 1; i <= 4; i++) {\n        for (int j = 1; j <= 7; j++) {\n            if (weights[i - 1] < j) table[i][j] = MAX(table[i - 1][j], values[i - 1] + table[i - 1][j - weights[i - 1]]);\n            else table[i][j] = table[i - 1][j];\n        }\n    }\n    printf(\"%d\\n\", table[4][7]);\n    return 0;\n}\n", "logic-c-exact-fit-left-out", 10, 10, 1, "            if (weights[i - 1] <= j) table[i][j] = MAX(table[i - 1][j], values[i - 1] + table[i - 1][j - weights[i - 1]]);" },
        { "knapsack.cpp", "#include <algorithm>\n#include <iostream>\n#include <utility>\n#include <vector>\n\nint knapsack(int capacity, const std::vector<std::pair<int, int>>& items) {\n    std::vector<std::vector<int>> table(items.size() + 1, std::vector<int>(capacity + 1, 0));\n    for (std::size_t i = 1; i <= items.size(); i++) {\n        auto [weight, value] = items[i - 1];\n        for (int j = 1; j <= capacity; j++) {\n            if (weight < j) {\n                table[i][j] = std::max(table[i - 1][j], value + table[i - 1][j - weight]);\n            } else {\n                table[i][j] = table[i - 1][j];\n            }\n        }\n    }\n    return table[items.size()][capacity];\n}\n\nint main() {\n    std::cout << knapsack(7, {{5, 10}, {4, 40}, {6, 30}, {3, 50}}) << std::endl;\n    return 0;\n}\n", "logic-cpp-exact-fit-left-out", 11, 11, 1, "            if (weight <= j) {" },
        { "knapsack.dart", "import 'dart:math';\n\nint knapsack(int capacity, List<List<int>> items) {\n  final table = List.generate(items.length + 1, (_) => List.filled(capacity + 1, 0));\n  for (var i = 1; i <= items.length; i++) {\n    final weight = items[i - 1][0], value = items[i - 1][1];\n    for (var j = 1; j <= capacity; j++) {\n      if (weight < j) {\n        table[i][j] = max(table[i - 1][j], value + table[i - 1][j - weight]);\n      } else {\n        table[i][j] = table[i - 1][j];\n      }\n    }\n  }\n  return table[items.length][capacity];\n}\n\nvoid main() {\n  print(knapsack(7, [[5, 10], [4, 40], [6, 30], [3, 50]]));\n}\n", "logic-dart-exact-fit-left-out", 8, 8, 1, "      if (weight <= j) {" },
        { "knapsack.f90", "program knapsack\n  implicit none\n  integer, parameter :: capacity = 7, count = 4\n  integer :: weights(count) = [5, 4, 6, 3], values(count) = [10, 40, 30, 50]\n  integer :: table(0:count, 0:capacity), i, j\n  table = 0\n  do i = 1, count\n    do j = 1, capacity\n      if (weights(i) < j) then\n        table(i, j) = max(table(i - 1, j), values(i) + table(i - 1, j - weights(i)))\n      else\n        table(i, j) = table(i - 1, j)\n      end if\n    end do\n  end do\n  print '(I0)', table(count, capacity)\nend program knapsack\n", "logic-fortran-exact-fit-left-out", 9, 9, 1, "      if (weights(i) <= j) then" },
        { "knapsack.go", "package main\n\nimport \"fmt\"\n\nfunc knapsack(capacity int, items [][2]int) int {\n\ttable := make([][]int, len(items)+1)\n\tfor i := range table {\n\t\ttable[i] = make([]int, capacity+1)\n\t}\n\tfor i := 1; i <= len(items); i++ {\n\t\tweight, value := items[i-1][0], items[i-1][1]\n\t\tfor j := 1; j <= capacity; j++ {\n\t\t\tif weight < j {\n\t\t\t\ttable[i][j] = max(table[i-1][j], value+table[i-1][j-weight])\n\t\t\t} else {\n\t\t\t\ttable[i][j] = table[i-1][j]\n\t\t\t}\n\t\t}\n\t}\n\treturn table[len(items)][capacity]\n}\n\nfunc main() {\n\tfmt.Println(knapsack(7, [][2]int{{5, 10}, {4, 40}, {6, 30}, {3, 50}}))\n}\n", "logic-go-exact-fit-left-out", 13, 13, 1, "\t\t\tif weight <= j {" },
        { "Knapsack.java", "public class Knapsack {\n    static int knapsack(int capacity, int[][] items) {\n        int[][] table = new int[items.length + 1][capacity + 1];\n        for (int i = 0; i <= items.length; i++) {\n            int weight = i > 0 ? items[i - 1][0] : 0;\n            int value = i > 0 ? items[i - 1][1] : 0;\n            for (int j = 0; j <= capacity; j++) {\n                if (i == 0 || j == 0) {\n                    table[i][j] = 0;\n                } else if (weight < j) {\n                    table[i][j] = Math.max(table[i - 1][j], value + table[i - 1][j - weight]);\n                } else {\n                    table[i][j] = table[i - 1][j];\n                }\n            }\n        }\n        return table[items.length][capacity];\n    }\n\n    public static void main(String[] args) {\n        System.out.println(knapsack(7, new int[][] {{5, 10}, {4, 40}, {6, 30}, {3, 50}}));\n    }\n}\n", "logic-java-exact-fit-left-out", 10, 10, 1, "                } else if (weight <= j) {" },
        { "knapsack.js", "function knapsack(capacity, items) {\n  const table = Array.from({ length: items.length + 1 }, () => new Array(capacity + 1).fill(0));\n  for (let i = 1; i <= items.length; i++) {\n    for (let j = 1; j <= capacity; j++) {\n      if (items[i - 1][0] < j) {\n        table[i][j] = Math.max(table[i - 1][j], items[i - 1][1] + table[i - 1][j - items[i - 1][0]]);\n      } else {\n        table[i][j] = table[i - 1][j];\n      }\n    }\n  }\n  return table[items.length][capacity];\n}\n\nconsole.log(knapsack(7, [[5, 10], [4, 40], [6, 30], [3, 50]]));\n", "logic-js-exact-fit-left-out", 5, 5, 1, "      if (items[i - 1][0] <= j) {" },
        { "knapsack.lua", "local function knapsack(capacity, items)\n  local table_of = {}\n  for i = 0, #items do\n    table_of[i] = {}\n    for j = 0, capacity do\n      table_of[i][j] = 0\n    end\n  end\n  for i = 1, #items do\n    local weight, value = items[i][1], items[i][2]\n    for j = 1, capacity do\n      if weight < j then\n        table_of[i][j] = math.max(table_of[i - 1][j], value + table_of[i - 1][j - weight])\n      else\n        table_of[i][j] = table_of[i - 1][j]\n      end\n    end\n  end\n  return table_of[#items][capacity]\nend\n\nprint(knapsack(7, { { 5, 10 }, { 4, 40 }, { 6, 30 }, { 3, 50 } }))\n", "logic-lua-exact-fit-left-out", 12, 12, 1, "      if weight <= j then" },
        { "knapsack.php", "<?php\nfunction knapsack(int $capacity, array $items): int\n{\n    $table = array_fill(0, count($items) + 1, array_fill(0, $capacity + 1, 0));\n    for ($i = 1; $i <= count($items); $i++) {\n        [$weight, $value] = $items[$i - 1];\n        for ($j = 1; $j <= $capacity; $j++) {\n            if ($weight < $j) {\n                $table[$i][$j] = max($table[$i - 1][$j], $value + $table[$i - 1][$j - $weight]);\n            } else {\n                $table[$i][$j] = $table[$i - 1][$j];\n            }\n        }\n    }\n    return $table[count($items)][$capacity];\n}\n\necho knapsack(7, [[5, 10], [4, 40], [6, 30], [3, 50]]), \"\\n\";\n", "logic-php-exact-fit-left-out", 8, 8, 1, "            if ($weight <= $j) {" },
        { "knapsack.pl", "use strict;\nuse warnings;\nuse List::Util qw(max);\n\nsub knapsack {\n    my ($capacity, @items) = @_;\n    my @table = map { [(0) x ($capacity + 1)] } 0 .. @items;\n    for my $i (1 .. @items) {\n        my ($weight, $value) = @{ $items[$i - 1] };\n        for my $j (1 .. $capacity) {\n            if ($weight < $j) {\n                $table[$i][$j] = max($table[$i - 1][$j], $value + $table[$i - 1][$j - $weight]);\n            } else {\n                $table[$i][$j] = $table[$i - 1][$j];\n            }\n        }\n    }\n    return $table[scalar @items][$capacity];\n}\n\nprint knapsack(7, [5, 10], [4, 40], [6, 30], [3, 50]), \"\\n\";\n", "logic-perl-exact-fit-left-out", 11, 11, 1, "            if ($weight <= $j) {" },
        { "knapsack.ps1", "function Get-Knapsack([int]$capacity, $items) {\n    $table = New-Object 'int[][]' ($items.Count + 1)\n    for ($i = 0; $i -le $items.Count; $i++) {\n        $table[$i] = New-Object int[] ($capacity + 1)\n    }\n    for ($i = 1; $i -le $items.Count; $i++) {\n        $weight, $value = $items[$i - 1]\n        for ($j = 1; $j -le $capacity; $j++) {\n            if ($weight -lt $j) {\n                $table[$i][$j] = [math]::Max($table[$i - 1][$j], $value + $table[$i - 1][$j - $weight])\n            } else {\n                $table[$i][$j] = $table[$i - 1][$j]\n            }\n        }\n    }\n    return $table[$items.Count][$capacity]\n}\n\nGet-Knapsack 7 @(@(5, 10), @(4, 40), @(6, 30), @(3, 50))\n", "logic-powershell-exact-fit-left-out", 9, 9, 1, "            if ($weight -le $j) {" },
        { "knapsack.py", "def knapsack(capacity, items):\n    table = [[0] * (capacity + 1) for _ in range(len(items) + 1)]\n    for i in range(1, len(items) + 1):\n        weight, value = items[i - 1]\n        for j in range(1, capacity + 1):\n            if weight < j:\n                table[i][j] = max(table[i - 1][j], value + table[i - 1][j - weight])\n            else:\n                table[i][j] = table[i - 1][j]\n    return table[len(items)][capacity]\n\n\nprint(knapsack(7, [(5, 10), (4, 40), (6, 30), (3, 50)]))\n", "logic-python-exact-fit-left-out", 6, 6, 1, "            if weight <= j:" },
