        { "knapsack.rs", "fn knapsack(capacity: usize, items: &[(usize, u32)]) -> u32 {\n    let mut table = vec![vec![0u32; capacity + 1]; items.len() + 1];\n    for i in 1..=items.len() {\n        let (weight, value) = items[i - 1];\n        for j in 1..=capacity {\n            if weight < j {\n                table[i][j] = table[i - 1][j].max(value + table[i - 1][j - weight]);\n            } else {\n                table[i][j] = table[i - 1][j];\n            }\n        }\n    }\n    table[items.len()][capacity]\n}\n\nfn main() {\n    println!(\"{}\", knapsack(7, &[(5, 10), (4, 40), (6, 30), (3, 50)]));\n}\n", "logic-rust-exact-fit-left-out", 6, 6, 1, "            if weight <= j {" },
        { "Knapsack.scala", "object Knapsack {\n  def knapsack(capacity: Int, items: Array[(Int, Int)]): Int = {\n    val table = Array.ofDim[Int](items.length + 1, capacity + 1)\n    for (i <- 1 to items.length; j <- 1 to capacity) {\n      val (weight, value) = items(i - 1)\n      if (weight < j) {\n        table(i)(j) = math.max(table(i - 1)(j), value + table(i - 1)(j - weight))\n      } else {\n        table(i)(j) = table(i - 1)(j)\n      }\n    }\n    table(items.length)(capacity)\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(knapsack(7, Array((5, 10), (4, 40), (6, 30), (3, 50))))\n  }\n}\n", "logic-scala-exact-fit-left-out", 6, 6, 1, "      if (weight <= j) {" },
        { "knapsack.ts", "function knapsack(capacity: number, items: [number, number][]): number {\n  const best: number[] = new Array<number>(capacity + 1).fill(0);\n  for (const [weight, value] of items) {\n    for (let j = capacity; j > 0; j--) {\n      if (weight < j) {\n        best[j] = Math.max(best[j], value + best[j - weight]);\n      }\n    }\n  }\n  return best[capacity];\n}\n\nconsole.log(knapsack(7, [[5, 10], [4, 40], [6, 30], [3, 50]]));\n", "logic-js-exact-fit-left-out", 5, 5, 1, "      if (weight <= j) {" },
