    [InlineData("knapsack.ts", "function knapsack(capacity: number, items: [number, number][]): number {\n  const best: number[] = new Array<number>(capacity + 1).fill(0);\n  for (const [weight, value] of items) {\n    for (let j = capacity; j > 0; j--) {\n      if (weight <= j) {\n        best[j] = Math.max(best[j], value + best[j - weight]);\n      }\n    }\n  }\n  return best[capacity];\n}\n\nconsole.log(knapsack(7, [[5, 10], [4, 40], [6, 30], [3, 50]]));\n")]
    [InlineData("Program.cs", "using System;\n\npublic static class Program\n{\n    static int Knapsack(int capacity, int[][] items)\n    {\n        var table = new int[items.Length + 1, capacity + 1];\n        for (int i = 1; i <= items.Length; i++)\n        {\n            int weight = items[i - 1][0], value = items[i - 1][1];\n            for (int j = 1; j <= capacity; j++)\n            {\n                if (j >= weight)\n                {\n                    table[i, j] = Math.Max(table[i - 1, j], value + table[i - 1, j - weight]);\n                }\n                else\n                {\n                    table[i, j] = table[i - 1, j];\n                }\n            }\n        }\n\n        return table[items.Length, capacity];\n    }\n\n    public static void Main()\n    {\n        Console.WriteLine(Knapsack(7, new[] { new[] { 5, 10 }, new[] { 4, 40 }, new[] { 6, 30 }, new[] { 3, 50 } }));\n    }\n}\n")]
