    [InlineData("window.py", "def window_sums(items, k):\n    sums = []\n    total = 0\n    for i in range(len(items)):\n        total += items[i]\n        if k < i + 1:\n            total -= items[i - k]\n        if i + 1 >= k:\n            sums.append(total)\n    return sums\n\n\nprint(*window_sums([1, 2, 3, 4, 5], 3))\n")]
    public void WhatFitsExactlyLetInIsLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("exact-fit-left-out", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
